('mathl1d_001', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 9x + 2 = 47, what is the value of x?', '["5.4", "5", "4.5", "45"]'::jsonb, 1, null, 'Subtract 2: 9x = 45. Divide by 9: x = 5.', 'published', 'import', now()),
('mathl1d_002', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 4(x − 3) = 20, what is the value of x?', null, null, '["8"]'::jsonb, 'Divide by 4: x − 3 = 5, so x = 8.', 'published', 'import', now()),
('mathl1d_003', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 15 = 2x + 7, what is the value of x?', '["8", "11", "4", "16"]'::jsonb, 2, null, 'Subtract 7: 8 = 2x, so x = 4.', 'published', 'import', now()),
('mathl1d_004', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 6x = 2x + 28, what is the value of x?', '["3.5", "4", "14", "7"]'::jsonb, 3, null, 'Subtract 2x: 4x = 28, so x = 7.', 'published', 'import', now()),
('mathl1d_005', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'A shirt and a hat cost $34 together. The shirt costs $10 more than the hat. How much does the hat cost, in dollars?', '["12", "22", "17", "10"]'::jsonb, 0, null, 'h + (h + 10) = 34, so 2h = 24 and h = 12.', 'published', 'import', now()),
('mathl1d_006', 'math', 1, 'Algebra', 'Linear functions', null, null, 'The function h is defined by h(x) = 8 − 3x. What is h(2)?', '["−2", "5", "14", "2"]'::jsonb, 3, null, 'h(2) = 8 − 6 = 2.', 'published', 'import', now()),
('mathl1d_007', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A line passes through (1, 5) and (4, 14). What is its slope?', null, null, '["3"]'::jsonb, 'Slope = (14 − 5) ÷ (4 − 1) = 9 ÷ 3 = 3.', 'published', 'import', now()),
('mathl1d_008', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A bucket holds 20 liters of water and leaks 2 liters each hour. Which equation gives the water W, in liters, after t hours?', '["W = 20 − 2t", "W = 20t − 2", "W = 22t", "W = 2t − 20"]'::jsonb, 0, null, 'Start at 20 and subtract 2 for each hour.', 'published', 'import', now()),
('mathl1d_009', 'math', 1, 'Algebra', 'Linear functions', null, null, 'Which line has a y-intercept of 6?', '["y = 6x − 2", "y = −2x + 6", "y = 6x", "y = x − 6"]'::jsonb, 1, null, 'In y = mx + b, b is the y-intercept. Only y = −2x + 6 has b = 6.', 'published', 'import', now()),
('mathl1d_010', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A tutor charges $30 per hour plus a $15 booking fee. How much does a 3-hour session cost, in dollars?', '["135", "90", "93", "105"]'::jsonb, 3, null, '30(3) + 15 = 105.', 'published', 'import', now()),
('mathl1d_011', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'x + y = 20
x − y = 8

What is the value of y?', '["14", "8", "6", "12"]'::jsonb, 2, null, 'Adding gives 2x = 28, so x = 14 and y = 6.', 'published', 'import', now()),
('mathl1d_012', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'y = 3x
x + y = 16

What is the value of y?', null, null, '["12"]'::jsonb, 'x + 3x = 16, so x = 4 and y = 12.', 'published', 'import', now()),
('mathl1d_013', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'Apples cost $1 each and oranges cost $2 each. Sara buys 10 pieces of fruit for $14. How many oranges does she buy?', '["7", "3", "4", "6"]'::jsonb, 2, null, 'a + o = 10 and a + 2o = 14. Subtracting: o = 4.', 'published', 'import', now()),
('mathl1d_014', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Which value of x is a solution to 3x + 1 > 13?', '["2", "5", "4", "3"]'::jsonb, 1, null, '3x > 12, so x > 4. Only 5 is greater than 4.', 'published', 'import', now()),
('mathl1d_015', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Jo has $50 and spends $6 a day on lunch. For how many whole days can she buy lunch before running out of money?', null, null, '["8"]'::jsonb, '6d ≤ 50 gives d ≤ 8.33..., so the greatest whole number of days is 8.', 'published', 'import', now()),
('mathl1d_016', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Which inequality means "y is no more than 25"?', '["y < 25", "y > 25", "y ≤ 25", "y ≥ 25"]'::jsonb, 2, null, '"No more than" means less than or equal to.', 'published', 'import', now()),
('mathl1d_017', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 7x − 2(x + 3)?', '["5x − 6", "5x + 6", "5x − 3", "9x − 6"]'::jsonb, 0, null, '7x − 2x − 6 = 5x − 6.', 'published', 'import', now()),
('mathl1d_018', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x^{2})^{4}?', '["x^{8}", "4x^{2}", "x^{16}", "x^{6}"]'::jsonb, 0, null, 'Multiply exponents: 2 × 4 = 8.', 'published', 'import', now()),
('mathl1d_019', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x + 5)(x + 1)?', '["x^{2} + 5", "x^{2} + 5x + 6", "x^{2} + 6x + 6", "x^{2} + 6x + 5"]'::jsonb, 3, null, 'x^{2} + x + 5x + 5 = x^{2} + 6x + 5.', 'published', 'import', now()),
('mathl1d_020', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 6x^{2} − 9x?', '["3x(2x − 3)", "6x(x − 9)", "3x(2x − 9)", "3(2x − 3)"]'::jsonb, 0, null, 'Factor out 3x: 3x(2x − 3).', 'published', 'import', now()),
('mathl1d_021', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'If x^{2} = 64 and x > 0, what is x?', '["16", "8", "32", "4"]'::jsonb, 1, null, 'The positive square root of 64 is 8.', 'published', 'import', now()),
('mathl1d_022', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'If 3x^{2} = 27 and x > 0, what is x?', null, null, '["3"]'::jsonb, 'x^{2} = 9, so x = 3.', 'published', 'import', now()),
('mathl1d_023', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'What are the solutions to x(x − 5) = 0?', '["x = −5 and x = 0", "x = 0 only", "x = 0 and x = 5", "x = 5 only"]'::jsonb, 2, null, 'A product equals 0 when a factor is 0: x = 0 or x − 5 = 0.', 'published', 'import', now()),
('mathl1d_024', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = 2x^{2} + 1. What is f(−2)?', '["−7", "9", "17", "5"]'::jsonb, 1, null, 'f(−2) = 2(4) + 1 = 9.', 'published', 'import', now()),
('mathl1d_025', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'A video''s views triple every week. It has 500 views now. How many views will it have in 2 weeks?', '["9,000", "4,500", "1,500", "3,000"]'::jsonb, 1, null, '500 × 3 × 3 = 4,500.', 'published', 'import', now()),
('mathl1d_026', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'Which point is on the graph of y = x^{2} + 2?', '["(2, 6)", "(−2, 2)", "(0, 0)", "(2, 4)"]'::jsonb, 0, null, '2^{2} + 2 = 6, so (2, 6) is on the graph.', 'published', 'import', now()),
('mathl1d_027', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A train travels 240 miles in 4 hours. At this rate, how far does it travel in 7 hours?', '["360", "420", "400", "480"]'::jsonb, 1, null, '240 ÷ 4 = 60 mph. 60 × 7 = 420.', 'published', 'import', now()),
('mathl1d_028', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A recipe uses 3 eggs for every 2 cups of flour. How many eggs are needed for 8 cups of flour?', null, null, '["12"]'::jsonb, '3/2 = e/8, so e = 12.', 'published', 'import', now()),
('mathl1d_029', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A pack of 8 batteries costs $6. What is the cost per battery, in dollars?', '["0.50", "1.33", "2.00", "0.75"]'::jsonb, 3, null, '6 ÷ 8 = 0.75.', 'published', 'import', now()),
('mathl1d_030', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'How many seconds are in 4.5 minutes?', '["300", "450", "270", "245"]'::jsonb, 2, null, '4.5 × 60 = 270.', 'published', 'import', now()),
('mathl1d_031', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'What is 20% of 150?', '["15", "75", "30", "20"]'::jsonb, 2, null, '0.20 × 150 = 30.', 'published', 'import', now()),
('mathl1d_032', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A $80 jacket is marked down 15%. What is the sale price, in dollars?', null, null, '["68"]'::jsonb, '15% of 80 is 12, so the price is 80 − 12 = 68.', 'published', 'import', now()),
('mathl1d_033', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A class has 30 students, and 12 of them ride the bus. What percent ride the bus?', '["30%", "60%", "12%", "40%"]'::jsonb, 3, null, '12 ÷ 30 = 0.40 = 40%.', 'published', 'import', now()),
('mathl1d_034', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'What is the mean of 10, 14, 15, and 21?', '["14.5", "14", "15", "60"]'::jsonb, 2, null, 'The sum is 60, and 60 ÷ 4 = 15.', 'published', 'import', now()),
('mathl1d_035', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'What is the median of 9, 4, 7, 12, 5?', '["9", "5", "7.4", "7"]'::jsonb, 3, null, 'In order: 4, 5, 7, 9, 12. The middle value is 7.', 'published', 'import', now()),
('mathl1d_036', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'A set of test scores has a high of 97 and a low of 68. What is the range?', null, null, '["29"]'::jsonb, '97 − 68 = 29.', 'published', 'import', now()),
('mathl1d_037', 'math', 1, 'Problem-Solving and Data Analysis', 'Two-variable data', null, '{"h": ["Day", "Total pages"], "r": [["2", "30"], ["3", "45"], ["4", "60"]]}'::jsonb, 'The table shows the number of pages Ravi reads. If the pattern continues, how many pages will he have read after 6 days?', '["75", "105", "90", "80"]'::jsonb, 2, null, 'He reads 15 pages a day (30 ÷ 2), so after 6 days he has read 90 pages.', 'published', 'import', now()),
('mathl1d_038', 'math', 1, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'As the number of hours a student practices piano increases, the number of mistakes made in a recital tends to decrease. What kind of association is this?', '["Negative", "Positive", "No association", "Constant"]'::jsonb, 0, null, 'One quantity goes up while the other goes down.', 'published', 'import', now()),
('mathl1d_039', 'math', 1, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A bag has 7 red and 3 blue tiles. One tile is picked at random. What is the probability it is red?', '["3/10", "7/10", "7/3", "3/7"]'::jsonb, 1, null, '7 of the 10 tiles are red.', 'published', 'import', now()),
('mathl1d_040', 'math', 1, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A number from 1 to 10 is chosen at random. What is the probability it is a multiple of 3?', '["3/10", "1/3", "2/5", "1/10"]'::jsonb, 0, null, 'The multiples of 3 are 3, 6, and 9: 3 out of 10.', 'published', 'import', now()),
('mathl1d_041', 'math', 1, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'In a random sample of 80 students, 20 said they play an instrument. The school has 1,200 students. About how many play an instrument?', '["300", "400", "960", "240"]'::jsonb, 0, null, '20/80 = 25%. 25% of 1,200 = 300.', 'published', 'import', now()),
('mathl1d_042', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A square has sides of 11 cm. What is its area, in square centimeters?', '["121", "111", "44", "22"]'::jsonb, 0, null, '11 × 11 = 121.', 'published', 'import', now()),
('mathl1d_043', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A fish tank is 24 inches long, 10 inches wide, and 12 inches tall. How many cubic inches of water does it hold when full?', null, null, '["2880", "2,880"]'::jsonb, 'Volume = 24 × 10 × 12 = 2,880 cubic inches.', 'published', 'import', now()),
('mathl1d_044', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangle has an area of 72 square inches and a length of 9 inches. What is its width?', '["63", "9", "7", "8"]'::jsonb, 3, null, '72 ÷ 9 = 8.', 'published', 'import', now()),
('mathl1d_045', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two angles of a triangle measure 45° and 65°. What is the third angle?', '["60°", "80°", "110°", "70°"]'::jsonb, 3, null, '180 − 45 − 65 = 70.', 'published', 'import', now()),
('mathl1d_046', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'An angle measures 28°. What is the measure of its complement?', '["152°", "72°", "62°", "28°"]'::jsonb, 2, null, '90 − 28 = 62.', 'published', 'import', now()),
('mathl1d_047', 'math', 1, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A kite''s string is 25 feet long and pulled tight. The kite is directly above a point on the ground 7 feet from where the string is held at ground level. How high is the kite, in feet?', null, null, '["24"]'::jsonb, 'The string is the hypotenuse: h^{2} + 7^{2} = 25^{2}, so h^{2} = 625 − 49 = 576 and h = 24.', 'published', 'import', now()),
('mathl1d_048', 'math', 1, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has a diameter of 18. What is its radius?', '["6", "9", "36", "18"]'::jsonb, 1, null, 'The radius is half the diameter.', 'published', 'import', now()),
('mathl1d_049', 'math', 1, 'Geometry and Trigonometry', 'Circles', null, null, 'A round table has a radius of 2 feet. What is its area, in square feet?', '["2π", "4π", "8π", "16π"]'::jsonb, 1, null, 'πr^{2} = π(4) = 4π.', 'published', 'import', now()),
('mathl2d_001', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'Mia''s age is 3 years less than twice Leo''s age. The sum of their ages is 27. How old is Mia?', '["24", "17", "10", "14"]'::jsonb, 1, null, 'm = 2L − 3 and m + L = 27. Then 3L − 3 = 27, so L = 10 and m = 17.', 'published', 'import', now()),
('mathl2d_002', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 6 − (x + 4) = 2(x − 5), what is the value of x?', null, null, '["4"]'::jsonb, 'Left: 2 − x. Right: 2x − 10. So 2 − x = 2x − 10, 12 = 3x and x = 4.', 'published', 'import', now()),
('mathl2d_003', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'The equation 1.8C + 32 = F converts Celsius to Fahrenheit. What Celsius temperature equals 95°F?', '["31.7", "53", "35", "63"]'::jsonb, 2, null, '1.8C = 63, so C = 35.', 'published', 'import', now()),
('mathl2d_004', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 2x + 3y = 12, what is the value of 4x + 6y?', '["18", "12", "36", "24"]'::jsonb, 3, null, '4x + 6y is 2(2x + 3y) = 2(12) = 24.', 'published', 'import', now()),
('mathl2d_005', 'math', 2, 'Algebra', 'Linear functions', null, '{"h": ["x", "f(x)"], "r": [["0", "7"], ["2", "13"], ["4", "19"]]}'::jsonb, 'The table shows values of a linear function f. What is f(10)?', '["30", "40", "34", "37"]'::jsonb, 3, null, 'f increases by 3 each time x increases by 1, and f(0) = 7, so f(x) = 3x + 7 and f(10) = 37.', 'published', 'import', now()),
('mathl2d_006', 'math', 2, 'Algebra', 'Linear functions', null, null, 'A line has slope 2/5 and passes through (10, 1). What is its y-intercept?', null, null, '["-3", "−3"]'::jsonb, '1 = (2/5)(10) + b = 4 + b, so b = −3.', 'published', 'import', now()),
('mathl2d_007', 'math', 2, 'Algebra', 'Linear functions', null, null, 'A phone''s battery is at 100% and drops 8% per hour of video. After how many hours of video will it be at 36%?', '["64", "4.5", "6", "8"]'::jsonb, 3, null, '100 − 8h = 36, so 8h = 64 and h = 8.', 'published', 'import', now()),
('mathl2d_008', 'math', 2, 'Algebra', 'Linear functions', null, null, 'In the equation y = 4.5x + 120, y is the number of words a typist has typed after x minutes, counting a draft typed earlier. What does 120 represent?', '["The number of words already typed before the typist started", "The number of words typed per hour", "The total number of minutes", "The typing speed in words per minute"]'::jsonb, 0, null, '120 is the value of y when x = 0, the starting number of words.', 'published', 'import', now()),
('mathl2d_009', 'math', 2, 'Algebra', 'Linear functions', null, null, 'Which equation represents a line perpendicular to y = 4x + 1 that passes through (0, −2)?', '["y = 4x − 2", "y = (1/4)x − 2", "y = −(1/4)x − 2", "y = −4x − 2"]'::jsonb, 2, null, 'A perpendicular line has slope −1/4, and the y-intercept is −2.', 'published', 'import', now()),
('mathl2d_010', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'y = −2x + 9
y = x − 3

What is the solution (x, y)?', '["(4, 1)", "(−4, 17)", "(3, 0)", "(1, 4)"]'::jsonb, 0, null, '−2x + 9 = x − 3 gives 3x = 12, x = 4, and y = 1.', 'published', 'import', now()),
('mathl2d_011', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'A café sold 50 drinks: coffees for $3 and teas for $2. It made $128. How many coffees were sold?', null, null, '["28"]'::jsonb, 'c + t = 50 and 3c + 2t = 128. Then 3c + 100 − 2c = 128, so c = 28.', 'published', 'import', now()),
('mathl2d_012', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'How many solutions does this system have?

